use serde_json::Value;

pub fn solve(input: Value) -> Value {
    if let Value::Array(arr) = input {
        let mut result = Vec::new();
        let mut sum = 0;
        for item in arr {
            if let Value::Number(num) = item {
                sum += num.as_i64().unwrap();
                result.push(Value::Number(serde_json::Number::from(sum)));
            }
        }
        Value::Array(result)
    } else {
        Value::Array(vec![])
    }
}
